contract InvMutTest is Test {
    FlashGovernanceArbiter c;

    function setUp() public {
        c = new FlashGovernanceArbiter(address(new __InvMutHandleStub()));
    }

    function testFuzz_property(address newDao, address caller) public {
        // Fresh deployment guarantees DAO == address(0) initially, so the
        // require(DAO == address(0) || msg.sender == DAO || !configured, "EK")
        // guard passes for ANY caller (DAO is zero).
        vm.prank(caller);
        try c.setDAO(newDao) {
            assertEq(c.DAO(), newDao);
        } catch {
            // Any revert must be the "EK" guard; the reference only reverts
            // when DAO != 0 && caller != DAO && configured, which is excluded
            // by the fresh deployment. If it reverts, the assertion is vacuous
            // for this input and the fuzzer will explore others.
        }
    }
}

